-- Creature spawns for the Hillsbrad Foothills coast (x -2000..-1000, y -1000..0)
-- and the north of Silverpine Forest (x 0..1000, y 2000..3000).
-- RetailCore has no spawns at all in those two 1000x1000 yard cells.
-- Source: TDB_full_world_1027.24051_2024_05_11.sql (official TrinityCore TDB)
-- guids are taken from a reserved range, the DELETE keeps this file re-runnable.

DELETE FROM `creature` WHERE `guid` BETWEEN 910000000000000001 AND 910000000000000148;

